<script setup lang="ts">
import { appUrl } from '../../composables/appUrl';
import PageHead from '../../components/PageHead.vue';
import ServerTable from "../../components/ServerTable.vue";
import ActionMenu from "../../components/ActionMenu.vue";
import {Head,Link,router,useForm} from '@inertiajs/vue3';
import {computed,onBeforeUnmount,reactive,ref,watch} from 'vue';
import AppLayout from '../../layouts/AppLayout.vue';
import ConfirmDialog from '../../components/ConfirmDialog.vue';
import type {PageRows} from '../../types/salesOrder';
import type {OpsProgram,OpsParticipant} from '../../types/operations';
import { useConfirmedMutation } from '../../composables/confirmedMutation';
const confirmation = useConfirmedMutation();
const { pending: confirming } = confirmation;
type Answer={id:number;peserta_id:number;nama:string;instansi:string;times?:string;tgl_isi:string};
type Detail={id:number;id_survey_jawaban:number;pertanyaan_teks:string;nilai:number|null;jawaban:string|null;nama:string};
const props=defineProps<{program:OpsProgram;rows:PageRows<OpsParticipant>;filters:Record<string,string>;blockers:string[];warnings:string[];canManage:boolean;survey:{enabled:boolean;status:string;url:string|null;answers:Answer[];details:Detail[];total:number;recap:{pertanyaan:string;rata:number|null;nilai:Record<string,number>;pilihan:Record<string,number>|null;jawaban:Detail[]}[]}}>();
const tab=computed(()=>props.filters.tab || 'peserta');
const f=reactive({q:'',...props.filters});
let timer: ReturnType<typeof setTimeout> | undefined;
watch(() => f.q, () => { clearTimeout(timer); timer=setTimeout(()=>router.get(appUrl(`/manage-peserta/${props.program.id}`),{q:f.q,tab:tab.value},{preserveState:true,preserveScroll:true,replace:true}),300); });
onBeforeUnmount(()=>clearTimeout(timer));
const editing=ref<OpsParticipant|null>(null), mode=ref('nama'), viewed=ref<number|null>(null);
const closeForm=useForm({});
const form=useForm({nama_sertifikat:'',sumber_konfirmasi:'',status_kirim:'belum',tgl_kirim:'',kirim_via:'',draft_kirim_date:'',lsp:'',skema:'',metode:'',hasil:'belum',no_sertifikat_bnsp:'',berlaku_sampai:'',tgl_terima_bnsp:'',tgl_kirim_bnsp:'',id_card:'belum',bukti:null as File|null});
function edit(x:OpsParticipant,action:string){editing.value=x;mode.value=action;form.clearErrors();form.defaults({nama_sertifikat:x.nama_sertifikat || x.nama,sumber_konfirmasi:'',status_kirim:x.status_kirim || 'belum',tgl_kirim:x.tgl_kirim || '',kirim_via:x.kirim_via || '',draft_kirim_date:x.draft_kirim_date || '',lsp:x.sertifikat_lsp || x.lsp || '',skema:x.skema || '',metode:x.metode || '',hasil:x.hasil || 'belum',no_sertifikat_bnsp:x.no_sertifikat_bnsp || '',berlaku_sampai:x.sertifikat_berlaku || x.tgl_habis_sertifikat || '',tgl_terima_bnsp:x.tgl_terima_bnsp || '',tgl_kirim_bnsp:x.tgl_kirim_bnsp || '',id_card:x.id_card || 'belum',bukti:null});form.reset();}
function save(){if(editing.value)return confirmation.form(form,'post',`/manage-peserta/peserta/${editing.value.id}/${mode.value}`,{title:`Simpan administrasi ${editing.value.nama}?`,text:'Perubahan dicatat dalam riwayat peserta.'},{forceFormData:true,onSuccess:()=>editing.value=null});}
function closeProgram(){return confirmation.form(closeForm,'post',`/manage-peserta/${props.program.id}/close`,{title:`Close Program ${props.program.nomor}?`,text:['Program tidak dapat dibuka kembali. Quotation, Invoice, serta pengajuan biaya baru akan dikunci.',...props.warnings,...props.blockers].join('\n'),confirmLabel:'Ya, Close Program',danger:true});}
function surveyStatus(action:'buka'|'tutup'){return confirmation.visit('post',`/manage-peserta/${props.program.id}/survey/${action}`,{},{title:`${action==='buka'?'Buka':'Tutup'} survey ${props.program.nomor}?`,text:action==='buka'?'Peserta dapat mengirim jawaban selama survey dibuka.':'Peserta tidak dapat mengirim jawaban setelah survey ditutup.',danger:action==='tutup'},{preserveScroll:true});}
</script>
<template><Head :title="program.nomor"/><AppLayout title="Manage Peserta" full-width><PageHead :title="`Peserta — ${program.nomor}`" :description="`${program.judul} ? ${program.jenis==='b2b'?'B2B':'Public'} ? ${program.company} ? ${program.tgl_mulai} s.d. ${program.tgl_selesai} ? ${program.lokasi} ? Trainer ${program.trainer || '—'} ? Peserta Deal ${rows.total} / ${program.target_peserta}`"><Link :href="appUrl('/manage-peserta')">← Semua Program</Link><a :href="appUrl(`/manage-peserta/${program.id}/excel`)">Export Excel</a></PageHead><section class="panel"><h2>{{program.judul}}</h2><p>{{program.jenis.toUpperCase()}} · {{program.company}} · {{program.tgl_mulai}} s.d. {{program.tgl_selesai}} · {{program.lokasi}}</p><p>Trainer: {{program.trainer}} · Target {{program.target_peserta}} peserta.</p><p v-if="program.closed_date" class="notice">Closed {{program.closed_date}}. Administrasi sertifikat/BNSP tetap tersedia.</p><template v-else><p v-for="b in blockers" :key="b">{{b}}</p><button v-if="canManage" type="button" :disabled="confirming" @click="closeProgram">Close Program</button></template><p v-for="e in closeForm.errors" :key="e" class="error" role="alert">{{e}}</p></section><div class="batch-card"><nav class="tabs" aria-label="Data program"><Link v-for="t in ['peserta','sertifikat','survey']" :key="t" :href="appUrl(`/manage-peserta/${program.id}?tab=${t}`)" :aria-current="tab===t?'page':undefined">{{t==='peserta'?'Daftar Peserta':t==='sertifikat'?'Sertifikat':'Survey'}}</Link></nav>
<div class="filters"><label class="grow">Cari<input v-model="f.q" type="search" maxlength="100" :placeholder="tab==='survey'?'Cari nama peserta atau nomor quotation…':tab==='sertifikat'?'Cari peserta atau nomor sertifikat…':'Cari kode, nama, instansi, kontak, atau quotation…'" /></label></div><template v-if="tab!=='survey'"><form class="filters" @submit.prevent="router.get(appUrl(`/manage-peserta/${program.id}`),f)"><a :href="appUrl(`/manage-peserta/${program.id}/excel`)">Export Excel</a><a v-if="tab==='sertifikat' && rows.total" :href="appUrl(`/manage-peserta/${program.id}/pdf/draft`)">Draft semua peserta</a></form><p v-if="tab==='sertifikat'" class="notice">Penerbitan sertifikat resmi menunggu format, penandatangan, dan aturan BA. Draft tanpa nomor untuk konfirmasi nama.</p><ServerTable :keyword="filters.q || ''" :url="appUrl(`/manage-peserta/${program.id}/data`)" label="Daftar Peserta" :columns='[{"title": "No", "orderable": false}, {"title":"Kode","orderable":true}, {"title": "Nama", "orderable": true}, {"title": "Instansi / Company", "orderable": true}, {"title": "No. WA", "orderable": true}, {"title": "Email", "orderable": true}, {"title": "No. Quotation", "orderable": true}, {"title": "Action", "orderable": false}]' :filters="{ ...filters, tab }" refresh-on-visit v-if="tab==='peserta'"><template #cell-0="{ row: p, number }">{{ number }}</template><template #cell-1="{row:p}"><span class="code">{{p.kode || '—'}}</span></template><template #cell-2="{ row: p, number }">{{ p.nama }}</template><template #cell-3="{ row: p, number }">{{ p.instansi }}</template><template #cell-4="{ row: p, number }">{{ p.no_wa }}</template><template #cell-5="{ row: p, number }">{{ p.email }}</template><template #cell-6="{ row: p, number }">{{ p.nomor_quotation }}</template><template #cell-7="{ row: p, number }"><ActionMenu><Link :href="appUrl(`/quotation/${p.id_quotation}`)">Lihat Quotation</Link><a :href="appUrl(`/manage-peserta/${program.id}/pdf/name-table?peserta=${p.id}`)" target="_blank" rel="noopener">Name Table</a><a :href="appUrl(`/manage-peserta/${program.id}/pdf/name-table`)">Cetak Name Table semua peserta</a><a :href="appUrl(`/manage-peserta/${program.id}/pdf/hadir`)">Cetak Daftar Hadir semua peserta</a></ActionMenu></template></ServerTable><ServerTable :keyword="filters.q || ''" :url="appUrl(`/manage-peserta/${program.id}/data`)" label="Sertifikat" :columns='[{"title": "No", "orderable": false}, {"title": "Peserta", "orderable": true}, {"title": "Nama di sertifikat", "orderable": true}, {"title": "Sertifikat Pelatihan", "orderable": true}, {"title": "Sertifikasi LSP / BNSP", "orderable": true}, {"title": "Berlaku sampai", "orderable": true}, {"title": "Action", "orderable": false}]' :filters="{ ...filters, tab }" refresh-on-visit v-else><template #cell-0="{ row: p, number }">{{ number }}</template><template #cell-1="{ row: p, number }">{{ p.nama }}<small>{{ p.instansi }}</small></template><template #cell-2="{ row: p, number }">{{ p.nama_sertifikat || p.nama }}<small>{{ p.nama_konfirmasi_date?"Terkonfirmasi":"Belum dikonfirmasi" }}</small></template><template #cell-3="{ row: p, number }">{{ p.no_sertifikat || "Belum terbit" }}<small>{{ p.status_kirim || "Belum dikirim" }}</small><small>Draft {{ p.draft_kirim_date || "Belum dikirim" }}</small></template><template #cell-4="{ row: p, number }">{{ p.no_sertifikat_bnsp || "—" }}<small>{{ p.sertifikat_lsp }} · {{ p.hasil }}</small></template><template #cell-5="{ row: p, number }">{{ p.sertifikat_berlaku || "—" }}</template><template #cell-6="{ row: p, number }"><ActionMenu><a :href="appUrl(`/manage-peserta/${program.id}/pdf/draft?peserta=${p.id}`)">Draft sertifikat</a><a v-if="p.has_bnsp_file" :href="appUrl(`/documents/bnsp/${p.sertifikat_id}`)">Unduh BNSP</a><button v-if="canManage" type="button" @click="edit(p,'nama')">Konfirmasi nama</button><button v-if="canManage" type="button" @click="edit(p,'draft-kirim')">Catat draft dikirim</button><button v-if="canManage && p.tipe!=='Pelatihan'" type="button" @click="edit(p,'bnsp')">Pengiriman &amp; Sertifikasi BNSP</button><button v-if="canManage && p.no_sertifikat" type="button" @click="edit(p,'pengiriman')">Pengiriman Sertifikat</button><button disabled title="Menunggu pengesahan BA">Buat Sertifikat resmi</button></ActionMenu></template></ServerTable></template>
<section v-else class="panel stack"><h2>Survey peserta</h2><p v-if="!survey.enabled" class="notice">Survei publik belum diaktifkan. Pertanyaan dan aturan final menunggu BA; contoh hanya untuk pengujian.</p><p>Status {{survey.status}} · {{survey.answers.length}} dari {{survey.total}} peserta sudah mengisi.</p><a v-if="survey.url" :href="survey.url">{{survey.url}}</a><div v-if="canManage && !program.closed_date"><button :disabled="!survey.enabled || confirming" @click="surveyStatus('buka')">Buka survey</button><button :disabled="survey.status!=='buka' || confirming" @click="surveyStatus('tutup')">Tutup survey</button></div><a :href="appUrl(`/manage-peserta/${program.id}/survey/excel`)">Export Excel jawaban</a><ServerTable :keyword="filters.q || ''" :url="appUrl(`/manage-peserta/${program.id}/data`)" label="Survey peserta" :columns='[{"title": "No", "orderable": false}, {"title": "Nama", "orderable": true}, {"title": "No. Quotation", "orderable": true}, {"title": "Status", "orderable": false}, {"title": "Waktu isi", "orderable": false}, {"title": "Action", "orderable": false}]' :filters="{ ...filters, tab }" refresh-on-visit ><template #cell-0="{ row: p, number }">{{ number }}</template><template #cell-1="{ row: p, number }">{{ p.nama }}<small>{{ p.instansi }}</small></template><template #cell-2="{ row: p, number }">{{ p.nomor_quotation }}</template><template #cell-3="{ row: p, number }">{{ survey.answers.some(a=>a.peserta_id===p.id)?"Sudah mengisi":"Belum mengisi" }}</template><template #cell-4="{ row: p, number }">{{ survey.answers.find(a=>a.peserta_id===p.id)?.tgl_isi || "—" }}</template><template #cell-5="{ row: p, number }"><button v-if="survey.answers.some(a=>a.peserta_id===p.id)" type="button" @click="viewed=survey.answers.find(a=>a.peserta_id===p.id)?.id || null">Lihat jawaban</button></template></ServerTable><h2>Rekap jawaban</h2><section v-for="s in survey.recap" :key="s.pertanyaan"><h3>{{s.pertanyaan}}</h3><p v-if="s.rata!==null">Rata-rata {{s.rata.toFixed(1)}} · Jumlah per nilai: {{s.nilai}}</p><p v-if="s.pilihan">Jumlah per pilihan: {{s.pilihan}}</p><p v-for="d in s.jawaban" :key="d.id">{{d.nama}}: {{d.jawaban}}</p></section></section>
</div>
<ConfirmDialog v-if="editing" :title="mode==='nama'?'Konfirmasi nama':mode==='draft-kirim'?'Catat draft dikirim':mode==='pengiriman'?'Pengiriman Sertifikat':'Pengiriman & Sertifikasi BNSP'" :busy="form.processing || confirming" @cancel="editing=null" @confirm="save"><p>{{editing.nama}}</p><template v-if="mode==='nama'"><label>Nama di sertifikat<input v-model="form.nama_sertifikat" maxlength="150" required/></label><label>Sumber konfirmasi (mis. WA 12-11)<input v-model="form.sumber_konfirmasi" maxlength="150"/></label></template><label v-else-if="mode==='draft-kirim'">Tanggal draft dikirim<input v-model="form.draft_kirim_date" type="date" required/></label><div v-else-if="mode==='pengiriman'" class="form-grid"><label>Status kirim<select v-model="form.status_kirim"><option value="belum">Belum dikirim</option><option value="soft">Dikirim softcopy</option><option value="hard">Dikirim hardcopy</option></select></label><label>Tanggal kirim<input v-model="form.tgl_kirim" type="date"/></label><label>Dikirim lewat<input v-model="form.kirim_via" maxlength="100"/></label></div><div v-else class="form-grid"><label>LSP<input v-model="form.lsp" maxlength="100"/></label><label>Skema<input v-model="form.skema" maxlength="150"/></label><label>Metode<select v-model="form.metode"><option value="">Belum diisi</option><option value="ukom">Uji Kompetensi</option><option value="porto">Portofolio</option></select></label><label>Hasil<select v-model="form.hasil"><option value="belum">Belum diuji</option><option value="kompeten">Kompeten</option><option value="belum_kompeten">Belum Kompeten</option></select></label><label>No. Sertifikat BNSP<input v-model="form.no_sertifikat_bnsp" maxlength="60"/></label><label>Berlaku sampai<input v-model="form.berlaku_sampai" type="date"/></label><label>Diterima dari LSP<input v-model="form.tgl_terima_bnsp" type="date"/></label><label>Dikirim ke peserta<input v-model="form.tgl_kirim_bnsp" type="date"/></label><label>ID Card<select v-model="form.id_card"><option value="belum">Belum</option><option value="sudah">Sudah</option></select></label><label>File BNSP PDF/JPG/PNG, maks. 5 MB<input type="file" accept=".pdf,.jpg,.jpeg,.png" @change="form.bukti=($event.target as HTMLInputElement).files?.[0] || null"/></label></div><p v-for="e in form.errors" :key="e" class="error" role="alert">{{e}}</p></ConfirmDialog>
<ConfirmDialog v-if="viewed" title="Jawaban Survey" confirm-label="Tutup" @cancel="viewed=null" @confirm="viewed=null"><p v-for="d in survey.details.filter(x=>x.id_survey_jawaban===viewed)" :key="d.id"><strong>{{d.pertanyaan_teks}}</strong><br>{{d.nilai ?? d.jawaban}}</p></ConfirmDialog>
</AppLayout></template>
